import sys
import math

def query(l, r, left_indices, right_indices):
    print(f"? {l} {r}")
    print(" ".join(map(str, left_indices)))
    print(" ".join(map(str, right_indices)))
    sys.stdout.flush()
    return int(input())

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        demagnetized = set()
        max_queries = n + math.floor(math.log2(n))

        # Initial query to get some information
        if max_queries > 0:
            f = query(1, 1, [1], [2])
            if f == 0:
                demagnetized.add(1)
                demagnetized.add(2)

        # Try to identify demagnetized magnets by comparing pairs
        for i in range(1, n + 1):
            if len(demagnetized) >= 2 and max_queries <= 0:
                break
            for j in range(i + 1, n + 1):
                if len(demagnetized) >= 2 and max_queries <= 1:
                    break
                if max_queries <= 0:
                    break
                f = query(1, 1, [i], [j])
                if f == 0:
                    demagnetized.add(i)
                    demagnetized.add(j)
                max_queries -= 1

        # Ensure we have at least 2 demagnetized magnets
        if len(demagnetized) < 2:
            for i in range(1, n + 1):
                if i not in demagnetized:
                    for j in range(i + 1, n + 1):
                        if j not in demagnetized:
                            f = query(1, 1, [i], [j])
                            if f == 0:
                                demagnetized.add(i)
                                demagnetized.add(j)
                            if len(demagnetized) >= 2:
                                break
                            max_queries -= 1
                        if len(demagnetized) >= 2:
                            break
                    if len(demagnetized) >= 2:
                        break

        print(f"! {len(demagnetized)} {' '.join(map(str, sorted(demagnetized)))}")

solve()
